window.DIGEST_ARCHIVE=window.DIGEST_ARCHIVE||{};window.DIGEST_ARCHIVE["2026-06-24"]={"date":"2026-06-24","dateKR":"2026년 6월 24일","dateEN":"24 June 2026","total":113,"sections":[{"code":"TOP","type":"news","kTitle":"Section 1. Top News","eTitle":"Section 1. Top News","items":[{"code":"TOP","title":"드루리 WCI 12% 급등…40피트당 3,969달러","src":"Drewry","date":"2026-06-18","kSum":"드루리 세계컨테이너운임지수(WCI)가 6월 18일 40피트 컨테이너당 3,969달러로 전주比 12% 상승했다. 태평양 횡단·아시아-유럽 항로 운임 강세가 견인했다.","eSum":"Drewry's World Container Index rose 12% to $3,969 per 40ft on 18 June, driven by Transpacific and Asia–Europe gains.","kImp":"성수기 수요와 결항으로 운임 상방 압력이 지속된다.","eImp":"Peak-season demand and blank sailings keep upward rate pressure.","url":"https://www.drewry.co.uk/supply-chain-advisors/supply-chain-expertise/world-container-index-assessed-by-drewry"},{"code":"TOP","title":"상하이-LA 운임 주간 31% 폭등…4,565달러","src":"Maritime Gateway","date":"2026-06","kSum":"상하이-로스앤젤레스 운임이 한 주 만에 31% 올라 40피트당 4,565달러를 기록했고, 상하이-뉴욕은 20% 상승한 5,505달러를 나타냈다.","eSum":"Shanghai–Los Angeles jumped 31% in a week to $4,565/40ft and Shanghai–New York rose 20% to $5,505.","kImp":"미·중 관세 휴전발 선적 폭주가 태평양 운임을 끌어올렸다.","eImp":"US–China tariff-truce front-loading is lifting Transpacific rates.","url":"https://www.maritimegateway.com/container-shipping-forecast-2026/"},{"code":"TOP","title":"이란산 원유 수출 90% 이상 급감…미국 봉쇄 효과","src":"Seatrade Maritime","date":"2026-06","kSum":"미국의 해상 봉쇄가 본격화되며 이란산 원유 수출이 90% 이상 급감한 것으로 나타났다. 글로벌 원유 무역흐름 재편이 가속되고 있다.","eSum":"Iran's crude exports plunged over 90% as the US blockade took effect, accelerating a reshuffle of global crude flows.","kImp":"원유 물동량 이탈이 탱커 톤마일과 운임에 영향을 준다.","eImp":"Lost barrels reshape tanker ton-mile demand and rates.","url":"https://www.seatrade-maritime.com/maritime-transportation/tankers"},{"code":"TOP","title":"7월 1일 벙커 조정 앞두고 선적 앞당기기","src":"ShipMate+","date":"2026-06","kSum":"7월 1일 예정된 벙커유 할증 조정을 앞두고 화주들이 선적을 앞당기며 성수기 수요가 조기 형성됐다. 선사는 할증 부과에 성공했다.","eSum":"Front-loading ahead of the 1 July bunker adjustment pulled peak-season demand forward, letting carriers push through surcharges.","kImp":"연료 비용 전가가 운임 구조에 반영되고 있다.","eImp":"Fuel-cost pass-through is feeding into the rate structure.","url":"https://www.shipmateplus.com/feeds/blog/ocean-freight-rates"},{"code":"TOP","title":"셰넌, 컨테이너 시장 2026 전망…리스크 상존","src":"Xeneta","date":"2026-06","kSum":"제네타(Xeneta)의 2026 해양 전망은 강한 수요와 지정학 리스크가 공존하는 구도를 제시했다. 경로 우회와 결항이 변동성을 키운다.","eSum":"Xeneta's 2026 Ocean Outlook frames a market of strong demand alongside persistent geopolitical risk, with reroutings and blanks driving volatility.","kImp":"하반기 수급 균형이 운임 방향을 좌우한다.","eImp":"H2 supply–demand balance will set the rate trajectory.","url":"https://www.xeneta.com/hubfs/2026%20Ocean%20Outlook.pdf"},{"code":"TOP","title":"HD현대, HMM 컨테이너선 수주로 18년 만 최대 박스선 발주","src":"Maritime Executive","date":"2026-06","kSum":"HD현대가 HMM의 LNG 이중연료 컨테이너선 신조를 확정하며 18년 만에 최대 규모의 박스선 발주를 기록했다. 한국 조선 수주 호조가 이어진다.","eSum":"HD Hyundai confirmed HMM's LNG dual-fuel boxship order, posting its highest containership ordering in 18 years amid Korea's yard boom.","kImp":"대형 컨선 발주가 중장기 선복 공급과 운임에 영향을 준다.","eImp":"Large boxship orders affect medium-term capacity and rates.","url":"https://maritime-executive.com/article/hd-hyundai-confirms-hmm-order-pushes-to-highest-boxship-orders-in-18-years"},{"code":"TOP","title":"선사 통합·운임 구조 재편…2026년 비용 변화","src":"Southern Star","date":"2026-06","kSum":"해운 선사 통합이 2026년 운임 구조를 바꾸고 있다. 점유율 경쟁과 공급 조절이 화주 비용에 직접 반영된다.","eSum":"Ocean-carrier consolidation is reshaping 2026 freight costs, with share competition and capacity discipline feeding directly into shipper costs.","kImp":"선사 구조 재편이 운임 변동성과 협상력을 좌우한다.","eImp":"Carrier restructuring shapes rate volatility and bargaining power.","url":"https://southernstarnavigation.com/ocean-carrier-consolidation-freight-costs-2026/"}]},{"code":"ACC","type":"accident","kTitle":"Section 2. Accidents","eTitle":"Section 2. Accidents","items":[{"code":"ACC","title":"케미컬선 보켐 마렝고, 오만 인근서 무인기 피격","src":"vesseltracker","date":"2026-06-13","kCause":"인도 선원 21명이 승선한 케미컬선 '보켐 마렝고(Bochem Marengo)'가 6월 13일 호르무즈 남측 통항로를 출항하던 중 오만 동쪽 약 6해리 해상에서 무인기(UAV)에 피격됐다. 좌현 선수부 선체가 밸러스트·화물탱크 구역에서 파열됐다.","eCause":"The chemical tanker Bochem Marengo, with 21 Indian crew, was struck by a UAV ~6 nm east of Oman on 13 June while outbound via the southern Hormuz corridor; the port forward hull was ripped open at ballast/cargo tanks.","kLes":"분쟁 해역 통항 시 위협평가·통항로 선택·선체 방호가 핵심이다.","eLes":"Threat assessment, lane selection and hull protection are critical when transiting conflict waters.","url":"https://www.vesseltracker.com/en/news/vessels.html"},{"code":"ACC","title":"노르드스테르넨, 그단스크 조선소 안벽 접촉","src":"shipwrecklog","date":"2026-06-19","kCause":"'노르드스테르넨(Nordstjernen)'이 6월 19일 폴란드 그단스크 임페리얼 조선소에서 이안 후 강을 따라 항행하던 중 선미 좌현이 안벽에 접촉했다. 좁은 수로 저속 조선 중 발생했다.","eCause":"The Nordstjernen allided with the quay at Imperial Shipyard, Gdansk on 19 June while manoeuvring along the river after casting off; the port stern struck the quay.","kLes":"협수로 저속 조선 시 선미 여유·조류 영향을 사전 평가해야 한다.","eLes":"Stern clearance and current effects must be pre-assessed in narrow, low-speed manoeuvres.","url":"https://shipwrecklog.com/log/category/grounding/"},{"code":"ACC","title":"여객선 이다, 스투베쾨빙 인근서 모터보트와 충돌","src":"Seatrade Maritime","date":"2026-06-20","kCause":"보괴-스투베쾨빙 항로를 운항하는 여객선 '이다(Ida)'가 6월 20일 오후 스투베쾨빙 항 북쪽 약 400m 해상에서 모터보트와 충돌했다. 모터보트 승선 3명은 부상이 없었다.","eCause":"The ferry Ida, operating Bogo–Stubbekobing, collided with a motorboat ~400 m north of Stubbekobing on the afternoon of 20 June; none of the three aboard the motorboat were injured.","kLes":"소형선 혼재 수역에서 견시 강화·조기 회피동작이 요구된다.","eLes":"Enhanced lookout and early avoidance are needed where small craft mix with ferries.","url":"https://www.seatrade-maritime.com/maritime-safety/accidents"},{"code":"ACC","title":"갑판화물선 LCT MSCI 1, 필리핀 해상서 좌초","src":"gCaptain","date":"2026-06-08","kCause":"89m·3,253DWT 갑판화물선 'LCT MSCI 1'이 6월 8일 필리핀 일로코스노르테 바독 앞 남중국해에서 좌초했다. 선장은 침몰 전 의도적으로 좌초시켰고 선원 15명 중 다수가 퇴선했다.","eCause":"The 89 m, 3,253 dwt deck-cargo vessel LCT MSCI 1 grounded off Badoc, Ilocos Norte on 8 June; the master intentionally beached her before sinking and most of the 15 crew abandoned ship.","kLes":"침수 비상 시 의도적 좌초는 인명우선 손상통제의 마지막 수단이다.","eLes":"Intentional beaching is a last-resort damage-control measure prioritising life when flooding is uncontrollable.","url":"https://gcaptain.com/category/incidents/ship-accidents/"},{"code":"ACC","title":"데본 베이 침몰 조사 종료…니켈광 화물 위험 재부각","src":"gCaptain","date":"2026-06","kCause":"K-라인 운항 벌커 '데본 베이(Devon Bay)' 침몰(1월·55,000톤 니켈광) 수색이 종료되며 니켈광 액상화 위험이 다시 부각됐다. 21명 중 6명이 사망했다.","eCause":"The search for the K-Line bulker Devon Bay (sank in January with 55,000 t nickel ore) ended, renewing focus on nickel-ore liquefaction risk; six of 21 crew died.","kLes":"니켈광 등 Group A 화물의 수분함량·TML 관리가 필수다.","eLes":"Moisture content and TML control are essential for Group A cargoes like nickel ore.","url":"https://gcaptain.com/search-ends-after-devon-bay-sinking-highlights-ongoing-nickel-ore-cargo-dangers/"},{"code":"ACC","title":"일반화물선, 카스피해서 침몰…선원 구조","src":"MarineTraffic","date":"2026-06","kCause":"카스피해에서 일반화물선이 침몰했으나 선원 전원이 구조됐다. 악천후·복원성 손실이 원인으로 지목되고 있다.","eCause":"A general cargo vessel sank in the Caspian Sea with all crew rescued; bad weather and loss of stability are cited as likely factors.","kLes":"소형 화물선의 적부·복원성 관리와 기상 회피가 중요하다.","eLes":"Stowage, stability management and weather avoidance are vital for small cargo ships.","url":"https://www.marinetraffic.com/en/maritime-news/14/accidents/2026/12628/general-cargo-vessel-sinks-in-caspian-sea-crew-rescued"},{"code":"ACC","title":"MAIB, 해양사고 보고 지침 발표","src":"SAFETY4SEA","date":"2026-06","kCause":"영국 해양사고조사국(MAIB)이 사고 보고 절차에 관한 지침을 발표했다. 보고 시점·범위·증거 보존 요건을 명확히 했다.","eCause":"The UK MAIB issued guidance on marine incident reporting, clarifying timing, scope and evidence-preservation requirements.","kLes":"정확·신속한 사고보고가 재발방지 교훈의 출발점이다.","eLes":"Accurate, prompt reporting is the starting point for lessons that prevent recurrence.","url":"https://safety4sea.com/uk-maib-guidance-on-marine-incident-reporting/"}]},{"code":"PSC","type":"news","kTitle":"Section 3. Port State Control","eTitle":"Section 3. Port State Control","items":[{"code":"PSC","title":"파리·도쿄 MoU, 9~11월 화물고박 집중점검(CIC)","src":"Paris MoU","date":"2026-06","kSum":"파리·도쿄 MoU가 2026년 9월 1일~11월 30일 화물고박(Cargo Securing) 집중점검(CIC)을 시행한다. 고박매뉴얼 준수·고박장비 상태·선원 역량을 표준 질문지로 확인한다.","eSum":"The Paris and Tokyo MoUs will run a joint Cargo Securing CIC from 1 Sept to 30 Nov 2026, verifying CSM compliance, lashing condition and crew competency via a standard questionnaire.","kImp":"CSM·고박장비 점검과 선원 교육을 사전 정비해야 한다.","eImp":"Pre-audit your CSM, lashing gear and crew training ahead of the campaign.","url":"https://parismou.org/"},{"code":"PSC","title":"MoU 간 정보공유…한 항만 억류, 타 권역서 표적","src":"marineinspection","date":"2026-06","kSum":"파리·도쿄 MoU 간 억류·결함 데이터가 공유돼 한 항만의 억류가 다른 권역 PSCO에게 노출된다. 아시아-태평양 입항 시 표적 점검 대상이 된다.","eSum":"Detention and deficiency data is shared between Paris and Tokyo MoUs, so a detention in one region is visible to PSCOs elsewhere and raises targeting on arrival.","kImp":"단일 억류가 글로벌 표적도를 끌어올려 후속 점검을 부른다.","eImp":"A single detention raises a ship's global targeting and invites follow-up inspections.","url":"https://marineinspection.app/blog/tokyo-mou-port-state-control-inspection-regime-targeting"},{"code":"PSC","title":"LR, PSC 대응 가이던스 갱신","src":"Lloyd's Register","date":"2026-06","kSum":"로이드선급(LR)이 PSC 점검 대비 가이던스를 갱신해 출항 전 자체점검·결함 시정 절차를 강조했다. 억류 리스크 선제 관리가 핵심이다.","eSum":"Lloyd's Register refreshed its PSC-readiness guidance, emphasising pre-departure self-inspection and deficiency rectification to manage detention risk.","kImp":"출항 전 셀프 PSC 점검이 억류 예방의 첫 단계다.","eImp":"Pre-departure self-inspection is the first step to avoiding detention.","url":"https://www.lr.org/en/services/classification-certification/port-state-control/"},{"code":"PSC","title":"파리 MoU, 억류·조치 기준 안내문 배포","src":"Paris MoU","date":"2026-06","kSum":"파리 MoU가 억류 및 후속 조치 기준에 관한 안내문을 배포해 PSCO의 판단 일관성과 시정 요건을 명확히 했다.","eSum":"The Paris MoU circulated guidance on detention and action-taken criteria, clarifying PSCO consistency and rectification requirements.","kImp":"억류 해제 요건과 재점검 절차를 사전 숙지해야 한다.","eImp":"Crews should know release requirements and re-inspection procedures in advance.","url":"https://parismou.org/sites/default/files/Information%20on%20detention%20and%20action%20taken.pdf"},{"code":"PSC","title":"Q1 억류 증가…건화물·노후선 표적도 상승","src":"marineinspection","date":"2026-06","kSum":"1분기 억류 증가세 속에 건화물·노후선의 표적도가 상승했다. 선령·선종·기국 이력이 점검 우선순위를 좌우한다.","eSum":"Amid rising Q1 detentions, targeting of dry-cargo and older tonnage increased; ship age, type and flag history drive inspection priority.","kImp":"노후선은 출항 전 정비·서류 정비를 한층 강화해야 한다.","eImp":"Older ships must intensify pre-departure maintenance and documentation.","url":"https://marineinspection.app/blog/paris-mou-vs-tokyo-mou-key-differences-psc-inspection-standards"},{"code":"PSC","title":"MoU 점검 체계 마스터링…결함 범주 이해","src":"Marine Public","date":"2026-06","kSum":"MoU 점검 체계를 숙지하고 주요 결함 범주를 이해하는 것이 억류 예방의 출발점이라는 가이드가 제시됐다.","eSum":"A guide stresses mastering the MoU inspection regime and understanding key deficiency categories as the basis for avoiding detention.","kImp":"점검 체계 이해가 출항 전 자체점검의 질을 높인다.","eImp":"Understanding the regime improves pre-departure self-inspection.","url":"https://www.marinepublic.com/blogs/marine-law/100831-psc-guide-mastering-the-mou-inspection-regime"}]},{"code":"PCTC","type":"news","kTitle":"Section 4. PCTC / Car Carriers","eTitle":"Section 4. PCTC / Car Carriers","items":[{"code":"PCTC","title":"회그 아우토라이너스, 세 번째 오로라급 인도","src":"Baird Maritime","date":"2026-06","kSum":"회그 아우토라이너스(Hoegh Autoliners)가 친환경 기술을 탑재한 세 번째 오로라(Aurora)급 PCTC '회그 오스트랄리스(Hoegh Australis)'를 인도받았다. 자동차 9,100대를 적재한다.","eSum":"Hoegh Autoliners took delivery of its third Aurora-class PCTC, Hoegh Australis, fitted with eco technologies and capable of carrying up to 9,100 cars.","kImp":"암모니아·메탄올 레디 대형 PCTC가 선대 표준으로 자리잡고 있다.","eImp":"Ammonia/methanol-ready large PCTCs are becoming the fleet standard.","url":"https://www.bairdmaritime.com/shipping/dry-cargo/pcc-pctc/hoegh-autoliners-takes-delivery-of-third-car-carrier-in-series"},{"code":"PCTC","title":"오로라급, 탄소중립 암모니아 추진 첫 PCTC","src":"Hoegh Autoliners","date":"2026-06","kSum":"오로라급은 DNV '암모니아 레디'·'메탄올 레디' 표기를 받았고 PCTC 부문 최초로 탄소중립 암모니아 운항을 목표로 한다.","eSum":"The Aurora class holds DNV 'ammonia-ready' and 'methanol-ready' notations and aims to be the first PCTC segment to run on carbon-neutral ammonia.","kImp":"연료 전환 옵션 확보가 PCTC 자산가치 방어에 유리하다.","eImp":"Fuel-flexibility options help defend PCTC asset values.","url":"https://www.hoeghautoliners.com/news/the-future-is-here-the-world-s-largest-and-most-environmentally-friendly-car-carrier-in-the"},{"code":"PCTC","title":"회그, 2027년 상반기까지 6개월마다 오로라 2척 인도","src":"Baird Maritime","date":"2026-06","kSum":"회그 아우토라이너스는 12척 오로라급을 2027년 상반기까지 6개월마다 2척씩 인도받을 예정이다. 선대 현대화가 빠르게 진행된다.","eSum":"Hoegh Autoliners expects two Aurora-class deliveries every six months until H1 2027, rapidly modernising its fleet.","kImp":"순차 인도가 노후선 대체와 수송능력 확대를 견인한다.","eImp":"Phased deliveries drive fleet renewal and capacity growth.","url":"https://www.bairdmaritime.com/shipping/dry-cargo/pcc-pctc/wallenius-wilhelmsens-car-carrier-newbuildings-to-have-increased-capacity"},{"code":"PCTC","title":"신형 증대형 자동차선 설계 협업 추진","src":"Baird Maritime","date":"2026-06","kSum":"발레니우스 빌헬름센을 위한 증대형 자동차선 설계 협업이 추진되며, 적재효율·연료효율을 동시에 끌어올리는 차세대 선형이 개발되고 있다.","eSum":"A new design collaboration for increased-capacity car carriers is underway for Wallenius Wilhelmsen, developing next-gen hulls that boost both stowage and fuel efficiency.","kImp":"차세대 선형 표준화가 운영비·배출 저감으로 이어진다.","eImp":"Standardised next-gen hulls translate to lower opex and emissions.","url":"https://www.bairdmaritime.com/shipping/dry-cargo/pcc-pctc/new-collaboration-to-design-increased-capacity-car-carriers-for-wallenius-wilhelmsen"},{"code":"PCTC","title":"PCTC 신조 인도 흐름…선복 공급 확대","src":"MarineLink","date":"2026-06","kSum":"대형 PCTC 신조 인도가 이어지며 선복 공급이 확대된다. 완성차 물동량 둔화 우려 속 수급 균형이 시험대에 오른다.","eSum":"Ongoing PCTC newbuild deliveries are expanding capacity, testing supply–demand balance amid concerns over softening vehicle volumes.","kImp":"공급 확대와 물동량 둔화가 운임 조정 압력을 만든다.","eImp":"Capacity growth amid softening volumes pressures rates.","url":"https://www.marinelink.com/news/maritime/pctc"}]},{"code":"WW","type":"news","kTitle":"Section 5. Wallenius Wilhelmsen","eTitle":"Section 5. Wallenius Wilhelmsen","items":[{"code":"WW","title":"발레니우스 빌헬름센, RoRo 약 128척 운영","src":"Wallenius Wilhelmsen","date":"2026-06","kSum":"발레니우스 빌헬름센 오션은 자동차·건설·광산·농기계와 브레이크벌크를 운송하는 RoRo 약 128척을 운영한다. 5개 선급으로 구성된다.","eSum":"Wallenius Wilhelmsen Ocean operates ~128 RoRo vessels across five classes, carrying autos, construction, mining and agricultural machinery plus breakbulk.","kImp":"다목적 RoRo 선대가 완성차 외 고중량 화물 수익을 보강한다.","eImp":"A versatile RoRo fleet supplements auto revenue with high-and-heavy cargo.","url":"https://www.walleniuswilhelmsen.com/what-we-do/ocean-transportation/our-vessels"},{"code":"WW","title":"세계 첫 풍력추진 RoRo, EU 900만 유로 확보","src":"Wallenius Wilhelmsen","date":"2026-06","kSum":"발레니우스 빌헬름센의 세계 최초 풍력추진 RoRo 선박이 EU로부터 900만 유로의 자금을 확보했다. 오셔버드(Orcelle) 콘셉트 상용화가 진전됐다.","eSum":"Wallenius Wilhelmsen's pioneering wind-powered RoRo secured EUR 9M in EU funding, advancing commercialisation of its wind-assist concept.","kImp":"풍력추진은 EU ETS·연료비 부담을 구조적으로 낮춘다.","eImp":"Wind propulsion structurally lowers EU ETS and fuel-cost exposure.","url":"https://www.walleniuswilhelmsen.com/news/worlds-first-wind-powered-roro-vessel-secures-eur-9m-in-eu-funding"},{"code":"WW","title":"신조 6척, 2026~27년 인도…현대차그룹 수요 대응","src":"Wallenius Wilhelmsen","date":"2026-06","kSum":"발레니우스 빌헬름센은 현대차그룹 등 완성차 파트너의 수요 증가에 대응해 신조 6척을 2026~2027년 인도받는다.","eSum":"Wallenius Wilhelmsen will take six newbuildings in 2026–2027 to meet rising demand from automotive partners including Hyundai Motor Group.","kImp":"장기 화주 계약이 신조 투자 회수를 뒷받침한다.","eImp":"Long-term shipper contracts underpin newbuild payback.","url":"https://www.walleniuswilhelmsen.com/schedules"},{"code":"WW","title":"발레니우스 빌헬름센, 2분기 실적 8월 11일 발표","src":"Wallenius Wilhelmsen","date":"2026-06","kSum":"발레니우스 빌헬름센은 차기 실적(2분기)을 8월 11일 발표할 예정이다. 운임·물동량·연료비 추이가 관전 포인트다.","eSum":"Wallenius Wilhelmsen will release its next (Q2) earnings on 11 August; rate, volume and fuel-cost trends are key watch points.","kImp":"실적 발표가 자동차선 시황 방향성을 가늠하는 지표가 된다.","eImp":"The release will be a gauge for car-carrier market direction.","url":"https://finance.yahoo.com/quote/WAWI.OL/"},{"code":"WW","title":"발레니우스 라인스, 친환경 선대 전환 지속","src":"Wallenius Lines","date":"2026-06","kSum":"발레니우스 라인스가 풍력보조·대체연료를 결합한 친환경 선대 전환을 지속하고 있다. 오셔버드 등 차세대 콘셉트가 핵심 축이다.","eSum":"Wallenius Lines continues its green-fleet transition combining wind-assist and alternative fuels, with next-gen concepts like Orcelle at the core.","kImp":"선대 탈탄소 전략이 화주 ESG 요구에 부응한다.","eImp":"Fleet decarbonisation aligns with shippers' ESG demands.","url":"https://walleniuslines.com/our-vessels/"}]},{"code":"EE","type":"news","kTitle":"Section 6. Energy Efficiency & Decarbonisation","eTitle":"Section 6. Energy Efficiency & Decarbonisation","items":[{"code":"EE","title":"코스코 시핑 리브라, 대형 2행정 메탄올 개조 성공","src":"Lloyd's Register","date":"2026-06","kSum":"컨테이너선 '코스코 시핑 리브라(COSCO Shipping Libra)'의 대형 2행정 엔진 메탄올 개조가 성공해 심해 항로에서 메탄올 전환의 기술적 타당성을 입증했다.","eSum":"A successful methanol retrofit of a large two-stroke engine on the boxship COSCO Shipping Libra proved methanol conversion is technically viable at the deep-sea end.","kImp":"대형선 메탄올 개조의 반복가능성이 전환 속도를 높인다.","eImp":"Repeatable large-ship methanol retrofits accelerate the transition.","url":"https://www.lr.org/en/knowledge/press-room/press-listing/press-release/2026/engine-retrofit-capability-builds-as-regulatory-uncertainty-delays-conversions/"},{"code":"EE","title":"메탄올, '실행가능성'으로 상업 선대 선도","src":"Global Maritime Forum","date":"2026-06","kSum":"메탄올은 실행가능성을 바탕으로 상업 선대 도입을 선도하는 반면, 암모니아는 최대 CO2 감축 잠재력을 갖되 엔진·NOx·N2O 제어와 녹색 공급이 과제다.","eSum":"Methanol leads commercial-fleet adoption on 'implementability', while ammonia offers the greatest CO2 cuts but needs validated engines, NOx/N2O controls and green supply.","kImp":"연료별 성숙도 차이가 단계적 전환 전략을 요구한다.","eImp":"Differing fuel maturity calls for a phased transition strategy.","url":"https://globalmaritimeforum.org/news/zero-emission-shipping-fuels-methanol-and-ammonia/"},{"code":"EE","title":"녹색 수소·암모니아, 해운 넷제로 견인","src":"Carbon Credits","date":"2026-06","kSum":"녹색 수소·암모니아가 해운 탈탄소의 핵심 경로로 부상하며 생산·공급망 구축이 본격화되고 있다. 청정연료 가용성이 관건이다.","eSum":"Green hydrogen and ammonia are emerging as core pathways for maritime net-zero, with production and supply-chain build-out accelerating; clean-fuel availability is the crux.","kImp":"연료 공급 인프라가 전환 속도의 병목이다.","eImp":"Fuel-supply infrastructure is the bottleneck for transition pace.","url":"https://carboncredits.com/green-hydrogen-and-ammonia-drive-maritime-decarbonization/"},{"code":"EE","title":"선박 에너지효율, 프로펠러·공기윤활 등 '스택' 개선","src":"Ship Universe","date":"2026-06","kSum":"선주들은 엔진 개조, 터보차저·프로펠러 주변 ESD, 축발전기, 공기윤활, 디지털 서비스를 결합한 '개선 스택'으로 연료효율을 끌어올리고 있다.","eSum":"Owners are stacking improvements — engine conversions, turbocharger work, propeller-area ESDs, shaft generators, air lubrication and digital services — to boost fuel efficiency.","kImp":"복합 개선이 단일 대형 프로젝트보다 비용효율적이다.","eImp":"Stacked upgrades are more cost-effective than a single big project.","url":"https://www.shipuniverse.com/8-marine-engine-retrofit-packages-and-propulsion-efficiency-services-worth-watching-in-2026/"},{"code":"EE","title":"RMI, 해운 탈탄소 경로 분석 발표","src":"RMI","date":"2026-06","kSum":"RMI가 해운 탈탄소 경로 분석을 발표해 연료·기술·정책 조합의 우선순위를 제시했다. 단기 효율개선과 장기 연료전환의 병행을 강조했다.","eSum":"RMI published maritime-decarbonisation pathway analysis, prioritising fuel/technology/policy combinations and stressing parallel near-term efficiency and long-term fuel switching.","kImp":"효율개선과 연료전환의 병행이 비용·리스크를 분산한다.","eImp":"Pairing efficiency gains with fuel switching spreads cost and risk.","url":"https://rmi.org/maritime-decarbonization/"},{"code":"EE","title":"IEA, 국제해운 배출 경로 점검","src":"IEA","date":"2026-06","kSum":"IEA가 국제해운 배출 경로를 점검하며 넷제로 정렬을 위한 연료·효율 투자 가속을 권고했다. 정책·시장 신호의 일관성이 중요하다.","eSum":"The IEA reviewed international-shipping emission pathways, urging accelerated fuel and efficiency investment for net-zero alignment; consistent policy and market signals are key.","kImp":"정책 신호 일관성이 투자 불확실성을 줄인다.","eImp":"Consistent policy signals reduce investment uncertainty.","url":"https://www.iea.org/energy-system/transport/international-shipping"},{"code":"EE","title":"암모니아·메탄올, 해상 탈탄소 경쟁","src":"Inspenet","date":"2026-06","kSum":"암모니아와 메탄올이 해상 탈탄소의 양대 후보로 경쟁하며 각자의 기술·공급 과제를 안고 있다. 단기 메탄올·장기 암모니아 구도가 형성된다.","eSum":"Ammonia and methanol compete as the two leading decarbonisation fuels, each with technical and supply challenges, forming a near-term methanol/long-term ammonia split.","kImp":"연료 경쟁 구도가 선대 전환 로드맵을 좌우한다.","eImp":"The fuel race shapes fleet-transition roadmaps.","url":"https://inspenet.com/en/articles/ammonia-and-methanol-decarbonize-the-seas/"}]},{"code":"DIG","type":"news","kTitle":"Section 7. Digitalization","eTitle":"Section 7. Digitalization","items":[{"code":"DIG","title":"해상 사이버 사고 103% 급증…스마트선박 표적","src":"Industrial Cyber","date":"2026-06","kSum":"2025년 해상 사이버 사고가 전년比 103% 급증했다. 보고서는 스마트선박이 표적이 되고 있다며 '시큐어 바이 디자인' 전환을 촉구했다.","eSum":"Maritime cyber incidents surged 103% in 2025; the report warns smart ships are under fire and urges a secure-by-design overhaul.","kImp":"연결성 확대가 공격면을 키워 선제 방어가 필요하다.","eImp":"Rising connectivity expands the attack surface, demanding proactive defence.","url":"https://industrialcyber.co/reports/maritime-cyber-incidents-jump-103-as-cytur-warns-smart-ships-under-fire-urges-secure-by-design-overhaul/"},{"code":"DIG","title":"에이전트형 자율공격 부상…공격수명주기 90% 수행","src":"economymiddleeast","date":"2026-06","kSum":"AI 에이전트가 공격수명주기의 최대 90%를 자율 수행하는 '에이전트형 자율공격' 단계가 부상하고 있다. 탐지가 어려운 자동화 공격이 늘어난다.","eSum":"Agent-based autonomous attacks are emerging, with AI agents performing up to 90% of the attack lifecycle — hard-to-detect automated intrusions.","kImp":"자동화 공격에 대응한 자동화 탐지·격리 체계가 요구된다.","eImp":"Automated detection and isolation are needed to counter automated attacks.","url":"https://economymiddleeast.com/news/maritime-sector-exposed-to-autonomous-cyberattacks-faster-than-ever/"},{"code":"DIG","title":"자율선 설계·AI 인프라 신규 이니셔티브 출범","src":"SAFETY4SEA","date":"2026-06","kSum":"AI 인프라와 자율선 설계를 진전시키기 위한 신규 이니셔티브가 출범했다. 업계 협업으로 표준·보증 체계 정비가 추진된다.","eSum":"New initiatives launched to advance AI infrastructure and autonomous-vessel design, with industry collaboration on standards and assurance.","kImp":"표준·보증 정비가 자율선 상용화의 전제다.","eImp":"Standards and assurance are prerequisites for autonomous-ship deployment.","url":"https://safety4sea.com/new-initiatives-formed-to-advance-ai-infrastructure-and-autonomous-vessel-design/"},{"code":"DIG","title":"MIT, 기술·정책 결합한 해상 사이버보안 제언","src":"MIT News","date":"2026-06","kSum":"MIT가 기술과 정책을 결합한 해상 사이버보안 강화 방안을 제시했다. 선박 시스템의 설계단계 보안과 규제 정합성을 강조했다.","eSum":"MIT proposed strengthening maritime cybersecurity by combining technology and policy, stressing design-stage security and regulatory alignment for ship systems.","kImp":"기술·규제 병행이 회복탄력성을 높인다.","eImp":"Combining technology and regulation boosts resilience.","url":"https://news.mit.edu/2026/enhancing-maritime-cybersecurity-technology-policy-strahinja-janjusevic-0225"},{"code":"DIG","title":"IMO, 해상 디지털화 글로벌 전략 개발 추진","src":"IMO","date":"2026-06","kSum":"IMO가 해상 디지털화를 위한 글로벌 전략 개발에 착수했다. 데이터 표준·전자정보교환·사이버 회복탄력성을 포괄한다.","eSum":"IMO is developing a global strategy for maritime digitalisation covering data standards, electronic information exchange and cyber resilience.","kImp":"국제 표준화가 디지털 전환의 상호운용성을 확보한다.","eImp":"International standardisation secures interoperability in the digital shift.","url":"https://www.imo.org/en/mediacentre/pressbriefings/pages/imo-global-strategy-maritime-digitalization.aspx"}]},{"code":"TECH","type":"news","kTitle":"Section 8. Ship Manager Technical Team","eTitle":"Section 8. Ship Manager Technical Team","items":[{"code":"TECH","title":"리비에라, 탱커 주기관 탈탄소 개조 분석","src":"Riviera","date":"2026-06","kSum":"리비에라는 탱커 주기관 탈탄소 개조의 기술·경제성을 분석하며 대체연료 전환과 효율장치 결합의 실무 고려사항을 제시했다.","eSum":"Riviera analysed decarbonisation retrofits of tanker main engines, outlining practical considerations for alternative-fuel conversion combined with efficiency devices.","kImp":"주기관 개조는 연료·효율장치 통합설계가 관건이다.","eImp":"Main-engine retrofits hinge on integrated fuel/efficiency design.","url":"https://www.rivieramm.com/news-content-hub/news-content-hub/decarbonisation-and-retrofitting-tanker-main-engines-78941"},{"code":"TECH","title":"심해 메탄올 개조, 반복가능 솔루션으로 진전","src":"Riviera","date":"2026-06","kSum":"코스코 시핑 리브라의 대형 2행정 메탄올 개조 성공으로 심해 항로 메탄올 전환이 반복가능한 솔루션으로 진전됐다.","eSum":"The successful large two-stroke methanol retrofit on COSCO Shipping Libra moved deep-sea methanol conversion toward repeatable solutions.","kImp":"검증된 개조 패키지가 선대 단위 전환을 가능케 한다.","eImp":"Validated retrofit packages enable fleet-scale conversion.","url":"https://www.rivieramm.com/expert-views/expert-views/shippings-journey-to-decarbonisation-engine-retrofitting-of-vessels-for-alternative-fuels"},{"code":"TECH","title":"선주, 노후선에 효율장치 '스택' 적용 확대","src":"Marine Log","date":"2026-06","kSum":"선주들은 기존 톤수에 엔진 튜닝·터보차저·프로펠러 ESD·축발전기·공기윤활·디지털 서비스를 결합 적용해 실연비를 끌어올리고 있다.","eSum":"Owners are applying stacked upgrades — engine tuning, turbochargers, propeller ESDs, shaft generators, air lubrication and digital services — to existing tonnage to lift real-world fuel performance.","kImp":"데이터 기반 진단이 개조 우선순위를 정한다.","eImp":"Data-driven diagnostics set retrofit priorities.","url":"https://www.marinelog.com/shiprepairusa2026/"}]},{"code":"HR","type":"news","kTitle":"Section 9. Marine HR","eTitle":"Section 9. Marine HR","items":[{"code":"HR","title":"다니카, 선원 부족에 임금 상승 지속","src":"SAFETY4SEA","date":"2026-06","kSum":"다니카(Danica)는 숙련 선원 부족으로 선원 임금 상승이 지속된다고 분석했다. 일부 직급은 2023년比 최대 10% 상승했다.","eSum":"Danica reports seafarer wages keep rising on skilled-crew shortage, with some ranks up to 10% higher than 2023.","kImp":"인력난이 인건비와 승선 유지율 관리 부담을 키운다.","eImp":"The shortage raises crew-cost and retention-management pressure.","url":"https://safety4sea.com/danica-seafarer-wages-keep-rising-due-to-crew-shortage/"},{"code":"HR","title":"STCW 사관 부족, 2026년 3배 확대 전망","src":"Maritime Hub","date":"2026-06","kSum":"STCW 인증 사관 부족이 2026년 3배로 확대될 전망이다. 1등기관사·1등항해사·전자기관사 부족이 특히 심각하다.","eSum":"The shortfall of STCW-certified officers is expected to triple by 2026, with Chief Engineers, Chief Officers and ETOs in especially short supply.","kImp":"핵심 직급 부족이 선대 운영 연속성을 위협한다.","eImp":"Shortages in key ranks threaten fleet-operating continuity.","url":"https://maritime-hub.com/global-seafarer-shortage-a-growing-crisis-for-world-trade/"},{"code":"HR","title":"선원 정신건강·복지 문제 여전","src":"Marine Insight","date":"2026-06","kSum":"임금 상승에도 선원 정신건강·복지 문제가 여전하다. 보고서는 식수·식량 부족과 임금 지연 사례를 지적했다.","eSum":"Despite rising wages, seafarer mental-health and welfare problems persist, with reports citing food/water shortages and delayed pay.","kImp":"복지 사각지대 해소가 안전·정주율 개선의 전제다.","eImp":"Closing welfare gaps underpins safety and retention.","url":"https://www.marineinsight.com/seafarer-salaries-continue-to-rise-but-mental-health-welfare-issues-persist-reports/"},{"code":"HR","title":"선원 25%, 식수·식량 부족 호소","src":"ITF Seafarers","date":"2026-06","kSum":"조사에서 선원 25%가 식수·식량 부족을 호소했고(2019년 20%↑), 35%는 임금 지연, 7%는 임금 미수령을 보고했다.","eSum":"A survey found 25% of seafarers reported lack of food and drinking water (up from 20% in 2019), 35% reported late pay and 7% did not receive full wages.","kImp":"기본 복지 미흡은 MLC 위반·결함 지적 위험을 키운다.","eImp":"Basic-welfare shortfalls raise MLC non-compliance and deficiency risk.","url":"https://www.itfseafarers.org/en/resources/wages"},{"code":"HR","title":"인도 출신 상급사관 임금, 최고 수준 유지","src":"Maritime Zone","date":"2026-06","kSum":"인도 출신 상급사관 임금이 동유럽·필리핀 동료 대비 약 10% 높은 최고 수준을 유지하고 있다. 직급별 임금 격차가 확대되고 있다.","eSum":"Senior officers from India continue to command the highest wages — about 10% above Eastern European and Filipino peers — widening rank-based pay gaps.","kImp":"국적·직급별 임금 경쟁이 채용 전략을 좌우한다.","eImp":"Nationality and rank pay competition shapes recruitment strategy.","url":"https://maritime-zone.com/en/analytics"},{"code":"HR","title":"2026 선원 임금 가이드…직급별 격차 확대","src":"Crewbase","date":"2026-06","kSum":"2026 선원 임금 가이드는 직급별 실질 임금과 격차 확대를 정리했다. 상급 직급 부족이 임금을 역사적 기준 위로 끌어올린다.","eSum":"The 2026 maritime salary guide details rank-by-rank pay and widening gaps, with senior-rank shortages pushing wages above historical benchmarks.","kImp":"임금 상승이 운항비 구조에 직접 반영된다.","eImp":"Wage inflation feeds directly into operating-cost structures.","url":"https://crewbase.pro/blog/2026/02/maritime-salary-guide-2026"},{"code":"HR","title":"시플라이, 직급별 선원 임금 가이드 갱신","src":"Seaplify","date":"2026-06","kSum":"시플라이(Seaplify)가 2026년 직급별 선원 임금 가이드를 갱신해 상급 직급의 임금 강세를 확인했다. 인력난이 임금 상방을 견인한다.","eSum":"Seaplify updated its 2026 seafarer salary guide by rank, confirming strength in senior-rank pay as the labour shortage drives wages up.","kImp":"직급별 임금 데이터가 채용·예산 계획에 활용된다.","eImp":"Rank-level pay data informs recruitment and budgeting.","url":"https://blog.seaplify.com/seafarer-salary-guide-by-rank/"}]},{"code":"HSEQ","type":"news","kTitle":"Section 10. HSEQ","eTitle":"Section 10. HSEQ","items":[{"code":"HSEQ","title":"교훈: 밀폐구역 진입 전 안전미팅 필수","src":"SAFETY4SEA","date":"2026-06","kSum":"밀폐구역 진입 전 안전미팅이 필수라는 교훈이 공유됐다. 절차 미준수가 치명적 결과로 이어진다는 점을 재확인했다.","eSum":"A lesson reaffirms a safety meeting is vital before enclosed-space entry; failing to follow procedures can be fatal.","kImp":"진입 전 가스측정·역할분담·구조계획 점검이 생명을 지킨다.","eImp":"Pre-entry gas testing, role assignment and rescue planning save lives.","url":"https://safety4sea.com/lessons-learned-prior-to-an-enclosed-space-entry-a-safety-meeting-is-vital/"},{"code":"HSEQ","title":"교훈: 밀폐구역 진입 훈련 강화 필요","src":"SAFETY4SEA","date":"2026-06","kSum":"밀폐구역 진입 관련 훈련을 강화해야 한다는 교훈이 제시됐다. 정기 훈련·장비 점검이 사고 예방의 핵심이다.","eSum":"A lesson highlights that enclosed-space entry training should be enhanced; regular drills and equipment checks are central to prevention.","kImp":"주기적 실습 훈련이 절차 이행 신뢰도를 높인다.","eImp":"Regular hands-on drills improve procedural reliability.","url":"https://safety4sea.com/lessons-learned-training-on-enclosed-space-entry-should-be-enhanced/"},{"code":"HSEQ","title":"교훈: 계류작업 중 신체 위치를 항상 평가하라","src":"SAFETY4SEA","date":"2026-06","kSum":"계류 스테이션에서 자신의 신체 위치(스냅백 존 등)를 항상 평가하라는 교훈이 공유됐다. 라인 파단 시 중상·사망 위험이 크다.","eSum":"A lesson urges always evaluating your physical position (snap-back zones) at a mooring station; line failure carries severe injury or death risk.","kImp":"스냅백 존 회피와 안전 위치 선정이 계류 사고를 줄인다.","eImp":"Avoiding snap-back zones and choosing safe positions cuts mooring casualties.","url":"https://safety4sea.com/lessons-learned-always-evaluate-your-physical-position-at-a-mooring-station/"},{"code":"HSEQ","title":"교훈: 안전작업체계(SSOW)를 항상 수립하라","src":"SAFETY4SEA","date":"2026-06","kSum":"자가계류·라프팅 등 작업에는 위험성평가·작업절차서를 포함한 안전작업체계(SSOW)를 항상 수립해야 한다는 교훈이 제시됐다.","eSum":"A lesson stresses always developing a safe system of work — incorporating risk assessments and method statements — for self-mooring/rafting operations.","kImp":"위험성평가·절차서가 비정형 작업의 안전을 담보한다.","eImp":"Risk assessments and method statements secure non-routine work.","url":"https://safety4sea.com/lessons-learned-a-safe-system-of-work-should-always-be-developed/"},{"code":"HSEQ","title":"밀폐구역 작업 종합 위험성평가 연구","src":"ScienceDirect","date":"2026-06","kSum":"선박 밀폐구역 작업에 대한 종합 위험성평가 연구가 발표돼 가스위험·구조지연·인적요인 등 주요 위험경로를 체계화했다.","eSum":"A comprehensive risk assessment of enclosed-space operations was published, systematising key hazard pathways — gas hazards, rescue delay and human factors.","kImp":"체계적 위험분석이 절차·훈련 개선의 근거가 된다.","eImp":"Systematic hazard analysis grounds procedure and training improvements.","url":"https://www.sciencedirect.com/science/article/pii/S0951832025007434"}]},{"code":"KR","type":"news","kTitle":"Section 11. Korean Shipping Market","eTitle":"Section 11. Korean Shipping Market","items":[{"code":"KR","title":"SCFI 2,985…7주 연속 상승, 1년 10개월 만에 최고","src":"코리아쉬핑가제트 (Korea Shipping Gazette)","date":"2026-06-12","kSum":"6월 12일자 상하이컨테이너운임지수(SCFI)가 2,985.22로 전주 2,726.48 대비 9% 올라 7주 연속 상승, 1년 10개월 만에 최고치를 기록했다.","eSum":"The Shanghai Containerized Freight Index reached 2,985.22 on 12 June, up 9% week-on-week from 2,726.48 — a seventh straight weekly gain and the highest in 22 months.","kImp":"중동 운임 강세가 SCFI 상승을 견인하고 있다.","eImp":"Middle East rate strength is driving the SCFI higher.","url":"https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147003"},{"code":"KR","title":"부산항만공사, 수입 공컨테이너 유해생물 합동 실태조사","src":"오션프레스 (Ocean Press)","date":"2026-06","kSum":"부산항만공사(BPA)가 6월 11~19일 북항 신선대부두·신항 4부두에서 수입 공(空)컨테이너를 통한 유해 외래생물 유입 차단을 위한 합동 실태조사를 실시했다.","eSum":"Busan Port Authority (BPA) ran a joint inspection of imported empty containers at Sinseondae (North Port) and HPNT (New Port) on 11–19 June to block invasive species entering via empties.","kImp":"검역 강화가 항만 생물안전·환경 리스크를 줄인다.","eImp":"Tighter quarantine reduces port biosecurity and environmental risk.","url":"https://www.oceanpress.co.kr/news/article.html?no=30358"},{"code":"KR","title":"부산항, 자동차운반선 LNG 벙커링 상업운영 개시","src":"코리아쉬핑가제트 (Korea Shipping Gazette)","date":"2026-06","kSum":"부산항에서 자동차운반선(PCTC) 대상 LNG 벙커링 상업운영이 개시됐다. 친환경 연료공급 인프라 확충으로 항만 경쟁력이 강화된다.","eSum":"Busan Port launched commercial LNG bunkering for car carriers (PCTC), expanding green-fuel supply infrastructure and boosting port competitiveness.","kImp":"LNG 벙커링 상용화가 부산항 대체연료 허브화를 뒷받침한다.","eImp":"Commercial LNG bunkering supports Busan's alt-fuel hub ambitions.","url":"https://www.ksg.co.kr/news/main_newsView.jsp?pNum=146983"},{"code":"KR","title":"국내 해운 3사, 매출 늘어도 영업이익 감소 전망","src":"CEO스코어데일리 (CEO Score Daily)","date":"2026-06","kSum":"국내 해운 3사(HMM·현대글로비스·팬오션)의 매출은 전년比 7.9% 증가하나 영업이익은 5.9% 감소할 것으로 집계됐다. 공급과잉·수요 위축이 부담이다.","eSum":"Korea's top three carriers (HMM, Hyundai Glovis, Pan Ocean) are projected to grow revenue 7.9% but see operating profit fall 5.9%, pressured by oversupply and soft demand.","kImp":"운임 변동성 속 수익성 방어가 핵심 과제다.","eImp":"Defending margins amid rate volatility is the key challenge.","url":"https://m.ceoscoredaily.com/page/view/2026011615253928422"},{"code":"KR","title":"HMM 본사 부산 이전 확정…매각 과제 병존","src":"인천투데이 (Incheon Today)","date":"2026-06","kSum":"HMM은 본사를 서울에서 부산으로 이전하기로 확정했다. 탄탄한 재무안정성을 바탕으로 부산 이전과 매각 재개 과제를 병행한다.","eSum":"HMM confirmed relocating its head office from Seoul to Busan, tackling the move alongside a revived privatisation agenda on the back of solid financials.","kImp":"지배구조·입지 변화가 중장기 경영전략을 좌우한다.","eImp":"Governance and location shifts shape its medium-term strategy.","url":"https://www.incheontoday.com/news/articleView.html?idxno=308371"},{"code":"KR","title":"조선 수주 호조 vs 해운 3중고…중동발 엇갈린 운명","src":"중앙일보 (Korea Daily)","date":"2026-06","kSum":"한국 조선은 수주 호조를 누리는 반면 해운은 수요·공급·지정학 3중고에 직면했다. 중동 리스크가 두 업종의 운명을 엇갈리게 한다.","eSum":"Korean shipbuilding enjoys an order boom while shipping faces a triple squeeze of demand, supply and geopolitics — Middle East risk splits their fortunes.","kImp":"중동 변수는 조선엔 호재, 해운엔 비용·불확실성으로 작용한다.","eImp":"Middle East risk aids yards but burdens carriers with cost and uncertainty.","url":"https://www.koreadaily.com/article/20260517130034614"},{"code":"KR","title":"HMM, 재무안정성 바탕 불황 대비","src":"KB의 생각 (KB Think)","date":"2026-06","kSum":"HMM이 탄탄한 재무안정성을 바탕으로 예고된 해운 불황에 대비하고 있다는 분석이 나왔다. 현금성 자산·낮은 부채가 완충재 역할을 한다.","eSum":"Analysis says HMM is preparing for a forecast downturn on solid financials, with cash holdings and low debt serving as a buffer.","kImp":"재무 완충력이 불황기 투자·배당 여력을 좌우한다.","eImp":"Financial buffers shape downturn-era investment and dividend capacity.","url":"https://kbthink.com/news-list/view.html?newsId=20251202083943539"},{"code":"KR","title":"부산항만공사, 5월 글로벌 해운·물류 동향 발표","src":"부산항만공사 (Busan Port Authority)","date":"2026-06","kSum":"부산항만공사(BPA)가 2026년 5월 글로벌 해운·물류 동향 자료를 발표했다. 운임·물동량·항만 통계가 정리됐다.","eSum":"Busan Port Authority (BPA) released its May 2026 global shipping and logistics trends report, compiling rate, volume and port statistics.","kImp":"항만 동향 자료가 화주·물류 의사결정의 근거가 된다.","eImp":"Port-trend data informs shipper and logistics decisions.","url":"https://www.busanpa.com/board/view.bpa?boardId=BBS_0000036&menuCd=DOM_000000105005004000&paging=ok&startPage=1&dataSid=36209"}]},{"code":"INS","type":"news","kTitle":"Section 12. Marine Insurance (P&I / H&M)","eTitle":"Section 12. Marine Insurance (P&I / H&M)","items":[{"code":"INS","title":"전쟁위험 보험료, 분쟁 전比 25~30배","src":"Property Casualty 360","date":"2026-06","kSum":"6월 기준 호르무즈 통항 전쟁위험 보험료가 선체가액의 2.5~3%로 분쟁 전 0.1% 대비 25~30배에 달한다. 7일 갱신 계약이 일반화됐다.","eSum":"War-risk premiums for Hormuz transit run 2.5–3% of hull value in June — 25–30x the pre-conflict 0.1% — typically on seven-day renewable terms.","kImp":"보험료 급등이 통항 결정과 운임 구조를 좌우한다.","eImp":"Premium spikes drive transit decisions and rate structures.","url":"https://www.propertycasualty360.com/fcs/2026/03/18/maritime-war-risk-insurance-in-the-2026-iran-crisis/"},{"code":"INS","title":"보험업계 \"위기 끝나지 않았다\"…보험료 고공","src":"claimsjournal","date":"2026-06","kSum":"해상 보험업계는 위기가 끝나지 않았다며 전쟁위험 보험료가 분쟁 전 대비 최대 30배로 유지된다고 경고했다. 통항 정상화에 시간이 걸린다.","eSum":"Marine insurers warn the crisis is far from over, with war-risk premiums still up to 30x pre-conflict levels; normalisation will take time.","kImp":"고보험료 장기화가 중동 통항 비용을 구조화한다.","eImp":"Persistently high premiums structurally raise Mideast transit costs.","url":"https://www.claimsjournal.com/news/national/2026/03/02/336002.htm"},{"code":"INS","title":"노스스탠다드, P&I·전쟁위험보험 상호작용 해설","src":"NorthStandard","date":"2026-06","kSum":"노스스탠다드가 P&I와 전쟁위험보험의 상호작용을 해설해, 분쟁 해역에서 담보 적용 범위와 면책 조항을 정리했다.","eSum":"NorthStandard explained the interaction between P&I and war-risk insurance, clarifying coverage scope and exclusions in conflict zones.","kImp":"담보 경계 이해가 분쟁 해역 통항 리스크 관리의 출발점이다.","eImp":"Understanding coverage boundaries is the basis for conflict-zone risk management.","url":"https://north-standard.com/insights-and-resources/resources/articles/the-interaction-between-pi-insurance-and-war-risks-insurance"},{"code":"INS","title":"전쟁위험보험 재개됐지만…'대가' 동반","src":"Caixin","date":"2026-06","kSum":"호르무즈 전쟁위험보험이 일부 재개됐으나 높은 보험료라는 대가를 동반했다. 인수 의지가 제한적이고 조건이 까다롭다.","eSum":"War-risk insurance returned to the Strait of Hormuz — but at a price, with limited appetite and stringent conditions.","kImp":"제한적 인수여력이 통항 가능 선박을 선별한다.","eImp":"Limited capacity screens which ships can transit.","url":"https://www.caixinglobal.com/2026-03-07/war-risk-insurance-returns-to-strait-of-hormuz-at-a-price-102420420.html"},{"code":"INS","title":"케네디스, 이란전쟁발 해상보험 리스크 재편 분석","src":"Kennedys","date":"2026-06","kSum":"케네디스(Kennedys)는 이란전쟁이 해상보험 리스크 지형을 재편하고 있다며 전쟁위험·P&I·선체보험 전반의 조건 변화를 진단했다.","eSum":"Kennedys analysed how the Iran war is reshaping the marine-insurance risk landscape, diagnosing changing terms across war-risk, P&I and hull cover.","kImp":"리스크 지형 변화가 보험 구조·요율 재설정을 부른다.","eImp":"A shifting risk landscape forces repricing and restructuring of cover.","url":"https://www.kennedyslaw.com/en/thought-leadership/article/2026/iran-war-triggers-a-reshaped-marine-insurance-risk-landscape/"},{"code":"INS","title":"선체보험, 충돌배상·사이버 담보 대응 점검","src":"Marsh","date":"2026-06","kSum":"마쉬(Marsh)는 P&I 담보가 충돌배상책임(사이버 포함)에 적절히 대응하는지 점검을 권고했다. 담보 공백 방지가 핵심이다.","eSum":"Marsh advised checking that P&I cover responds to collision liability, including cyber, to prevent coverage gaps.","kImp":"담보 적합성 점검이 대형 배상 리스크를 차단한다.","eImp":"Verifying cover adequacy guards against large liability exposure.","url":"https://www.marsh.com/en-gb/industries/marine/insights/protection-and-indemnity-cover-and-collision-liability.html"},{"code":"INS","title":"휴전에도 호르무즈 전쟁위험료 인하 어렵다","src":"House of Saud","date":"2026-06","kSum":"휴전이 성립돼도 호르무즈 전쟁위험 보험료는 쉽게 내리지 않는다는 분석이 나왔다. 무사고 통항 데이터 축적에 수년이 걸리기 때문이다.","eSum":"Analysis says a ceasefire won't quickly lower Hormuz war-risk premiums, as actuarial pricing resets only after years of incident-free transit data.","kImp":"보험료 경직성이 통항 비용을 장기간 높게 유지한다.","eImp":"Premium stickiness keeps transit costs elevated for years.","url":"https://houseofsaud.com/ceasefire-wont-lower-hormuz-war-risk-premium/"},{"code":"INS","title":"오일 슈퍼탱커 운임, 보험사 전쟁위험 철수에 사상 최고","src":"CNBC","date":"2026-06","kSum":"보험사들이 중동 전쟁위험 담보를 철회하면서 오일 슈퍼탱커(VLCC) 운임이 사상 최고로 치솟았다는 보도가 나왔다.","eSum":"Oil supertanker (VLCC) rates hit all-time highs as insurers dropped war-risk protection in the Middle East.","kImp":"담보 철수가 운임 급등과 통항 비용 폭증을 부른다.","eImp":"Cover withdrawal drives rate spikes and soaring transit costs.","url":"https://www.cnbc.com/2026/03/03/middle-east-crisis-iran-us-shipping-oil-tankers-strait-of-hormuz.html"}]},{"code":"VET","type":"news","kTitle":"Section 13. Vetting (RightShip / SIRE)","eTitle":"Section 13. Vetting (RightShip / SIRE)","items":[{"code":"VET","title":"SIRE 2.0, 알고리즘 기반 맞춤 점검 정착","src":"OCIMF","date":"2026-06","kSum":"SIRE 2.0가 VIQ7을 대체해 정착하며, 약 100개 맞춤 질문으로 선원 역량·하드웨어·절차를 통합 평가한다. 디지털 기록 기반으로 점검이 표준화됐다.","eSum":"SIRE 2.0 has bedded in as VIQ7's replacement, using ~100 tailored questions to assess crew competency, hardware and procedures via digitally recorded inspections.","kImp":"역량 중심 점검이 인적요인 관리의 중요성을 부각한다.","eImp":"Competency-focused inspection elevates human-factor management.","url":"https://www.ocimf.org/programmes/sire-2-0"},{"code":"VET","title":"JRS, SIRE 2.0 점검 가이드 발간","src":"JRS Innovation","date":"2026-06","kSum":"JRS이 SIRE 2.0 점검 가이드(2026)를 발간해 OCIMF 탱커 베팅·CVIQ·준수 요건을 정리했다. 실무 준비 체크리스트를 제공한다.","eSum":"JRS published a SIRE 2.0 inspection guide (2026) covering OCIMF tanker vetting, CVIQ and compliance, with a practical preparation checklist.","kImp":"구조화된 준비가 점검 결함·지연을 줄인다.","eImp":"Structured preparation reduces inspection findings and delays.","url":"https://marine.jrsinnovation.com/blog/sire-2-0-inspection-guide-ocimf-tanker-vetting-programme-2026"},{"code":"VET","title":"리비에라, \"SIRE는 여전히 목적에 부합하는가\" 점검","src":"Riviera","date":"2026-06","kSum":"리비에라가 탱커 베팅에서 SIRE가 여전히 목적에 부합하는지 점검하는 분석을 내놨다. 제도 실효성·부담·디지털화 균형이 논의됐다.","eSum":"Riviera examined whether SIRE remains fit for purpose in tanker vetting, debating the balance of effectiveness, burden and digitalisation.","kImp":"제도 실효성 논의가 차기 베팅 표준 진화를 예고한다.","eImp":"Debate on effectiveness signals the next evolution of vetting standards.","url":"https://www.rivieramm.com/news-content-hub/news-content-hub/tanker-vetting-is-sire-still-fit-for-purpose-60677"},{"code":"VET","title":"OCIMF SIRE 2.0, 영국 탱커 점검 가이드","src":"marineinspection","date":"2026-06","kSum":"OCIMF SIRE 2.0 기반 영국 탱커 점검 가이드가 제시됐다. 점검 준비·CVIQ·준수 요건의 실무 체크포인트를 담았다.","eSum":"An OCIMF SIRE 2.0 vessel-inspection guide for UK tankers was issued, with practical checkpoints for preparation, CVIQ and compliance.","kImp":"국가·항만별 점검 준비 차이를 사전 반영해야 한다.","eImp":"Prepare for country- and port-specific inspection nuances.","url":"https://marineinspection.app/blog/ocimf-sire-2-0-vessel-inspection-guide-uk-tankers"}]},{"code":"CLASS","type":"news","kTitle":"Section 14. Classification Societies","eTitle":"Section 14. Classification Societies","items":[{"code":"CLASS","title":"DNV, 7월 1일 규정 77건 발효 예정","src":"DNV","date":"2026-06","kSum":"DNV가 업계 의견수렴 절차를 거쳐 7월 1일 규정·표준 77건을 발효할 예정이다. 선급 규정 정비가 신조·운항 요건에 반영된다.","eSum":"DNV has 77 rule and standard documents planned to enter into force on 1 July following an industry hearing process.","kImp":"규정 갱신이 신조 사양·검사 요건 변경으로 이어진다.","eImp":"Rule updates translate to changed newbuild specs and survey requirements.","url":"https://www.dnv.com/rules-standards/"},{"code":"CLASS","title":"IACS 12개 정회원 체제 유지…ABS·DNV·LR·NK·KR 등","src":"MetaCAD","date":"2026-06","kSum":"국제선급연합회(IACS)는 ABS·DNV·LR·NK·KR·BV 등 12개 정회원 체제를 유지하며 국제 규정 조화를 주도한다. 한국선급(KR)도 정회원이다.","eSum":"IACS maintains its 12 full members — ABS, DNV, LR, NK, KR, BV and others — leading harmonisation of international rules; Korean Register (KR) is a full member.","kImp":"선급 간 규정 조화가 글로벌 검사 일관성을 확보한다.","eImp":"Cross-society harmonisation secures global survey consistency.","url":"https://metacad.io/en/regulation/classification-societies/"},{"code":"CLASS","title":"선급, 암모니아·메탄올 레디 표기 확대","src":"Marine Insight","date":"2026-06","kSum":"선급들이 '암모니아 레디'·'메탄올 레디' 표기를 확대하며 대체연료 전환을 뒷받침한다. 신조 발주 시 연료 유연성 표기가 표준화되고 있다.","eSum":"Class societies are expanding 'ammonia-ready' and 'methanol-ready' notations to support fuel transition, standardising fuel-flexibility notations at newbuild ordering.","kImp":"연료 레디 표기가 자산가치·재판매성을 보강한다.","eImp":"Fuel-ready notations bolster asset value and resale.","url":"https://www.marineinsight.com/maritime-law/classification-societies-in-the-world/"},{"code":"CLASS","title":"EMSA, 인정기관(선급) 평가 지속","src":"EMSA","date":"2026-06","kSum":"유럽해사안전청(EMSA)이 인정기관(선급) 평가를 지속하며 EU 항만 입항선 검사 품질을 관리한다. 선급 성과가 PSC·기국 신뢰와 연동된다.","eSum":"EMSA continues assessing recognised organisations (class societies) to manage inspection quality for ships calling at EU ports; class performance links to PSC and flag confidence.","kImp":"선급 품질평가가 EU 항만 통항 신뢰도에 직접 영향한다.","eImp":"RO quality assessment directly affects EU-port confidence.","url":"https://www.emsa.europa.eu/inspections/assessment-of-classification-societies.html"},{"code":"CLASS","title":"IACS, 12개 선급 중심 국제규정 조화 주도","src":"OE Digital","date":"2026-06","kSum":"IACS 12개 선급이 국제규정 조화와 통일해석(UI) 개발을 주도하며 신연료·디지털·사이버 분야 표준을 정비한다.","eSum":"The 12 IACS societies lead harmonisation and unified-interpretation development, advancing standards for novel fuels, digitalisation and cyber.","kImp":"통일해석이 선급 간 검사·승인 일관성을 확보한다.","eImp":"Unified interpretations ensure cross-society consistency.","url":"https://www.oedigital.com/classification-societies"}]},{"code":"COMM","type":"news","kTitle":"Section 15. Commercial / Charter Market","eTitle":"Section 15. Commercial / Charter Market","items":[{"code":"COMM","title":"케이프사이즈, 6월 18일 이후 최저로 하락","src":"HandyBulk","date":"2026-06","kSum":"케이프사이즈 지수가 4,046으로 0.7% 하락해 6월 18일 이후 최저를 기록했다. 15만 톤급 철광석·석탄 수송 수요가 약화됐다.","eSum":"The capesize index slipped 0.7% to 4,046, the lowest since 18 June, as demand for 150,000-t iron-ore and coal cargoes weakened.","kImp":"대형 벌커 운임 변동이 광물 무역 흐름을 반영한다.","eImp":"Large-bulker rate swings mirror mineral-trade flows.","url":"https://www.handybulk.com/baltic-dry-index/"},{"code":"COMM","title":"탱커 정기용선료, 6개월 9.98만 달러로 상승","src":"Baltic Exchange","date":"2026-06","kSum":"6월 초 탱커 6개월 정기용선료가 1,700달러 올라 일 99,800달러를 기록했고, 3년물은 1,900달러 오른 79,900달러를 나타냈다.","eSum":"In early June, six-month tanker time-charter rose $1,700 to $99,800/day and the three-year assessment gained $1,900 to $79,900/day.","kImp":"중동 혼란발 탱커 운임 강세가 용선료를 끌어올린다.","eImp":"Mideast-driven tanker strength lifts charter rates.","url":"https://www.balticexchange.com/en/data-services/market-information0/indices.html"},{"code":"COMM","title":"12개월 탱커 용선료는 소폭 하락…8.01만 달러","src":"Baltic Exchange","date":"2026-06","kSum":"6월 초 탱커 12개월 정기용선료는 200달러 내린 일 80,100달러로 소폭 하락했다. 단기·장기 기간물 간 방향성이 엇갈렸다.","eSum":"The 12-month tanker time-charter eased $200 to $80,100/day in early June, with short- and long-tenor assessments diverging.","kImp":"기간물별 엇갈림이 시황 전환점 신호일 수 있다.","eImp":"Tenor divergence may signal a market inflection.","url":"https://www.balticexchange.com/en/data-services/market-information0/dry-services.html"},{"code":"COMM","title":"컨테이너 운임지수, 동서항로 급등에 강세 지속","src":"TradingEconomics","date":"2026-06","kSum":"컨테이너 운임지수가 태평양 횡단·아시아-유럽 항로 급등으로 강세를 지속한다. 결항·성수기 수요·할증 부과가 상방을 받친다.","eSum":"The container freight index stays firm on Transpacific and Asia–Europe spikes, supported by blank sailings, peak-season demand and surcharges.","kImp":"구간별 격차 확대가 화주 비용 부담을 키운다.","eImp":"Widening lane gaps raise shipper cost burdens.","url":"https://tradingeconomics.com/commodity/containerized-freight-index"},{"code":"COMM","title":"피언리스 주간보고…탱커·벌크 운임 점검","src":"Fearnleys","date":"2026-06","kSum":"피언리스 주간보고가 탱커·벌크 운임 동향을 점검했다. 중동 변수와 물동량 흐름이 단기 운임 방향을 좌우한다.","eSum":"The Fearnleys weekly report reviewed tanker and bulk rate trends, with Middle East risk and cargo flows steering near-term direction.","kImp":"주간 시황 점검이 용선·배선 의사결정에 활용된다.","eImp":"Weekly market reviews inform chartering and deployment decisions.","url":"https://fearnpulse.com/"},{"code":"COMM","title":"LNG선 발주잔량 400척 돌파…선대의 50% 육박","src":"ShipFinex","date":"2026-06","kSum":"2026년 초 LNG선 발주잔량이 400척을 넘어 기존 선대의 약 50%에 육박했다. 공급 확대가 중장기 용선료에 부담으로 작용할 수 있다.","eSum":"The LNG-carrier orderbook topped 400 ships in early 2026, nearing 50% of the existing fleet — a potential drag on medium-term charter rates.","kImp":"대규모 신조가 가스선 수급 균형을 시험한다.","eImp":"A large orderbook will test gas-carrier supply–demand balance.","url":"https://www.shipfinex.com/blog/lng-carrier-construction-activity-orderbook"},{"code":"COMM","title":"발틱 주간 건화물 보고…벌커 운임 점검","src":"Baltic Exchange","date":"2026-06","kSum":"발틱 익스체인지 주간 건화물 보고가 케이프·파나막스·수프라막스 운임 동향을 점검했다. 물동량·항로별 수급이 운임을 좌우한다.","eSum":"The Baltic Exchange weekly dry report reviewed capesize, panamax and supramax rate trends, with cargo flows and lane balances steering rates.","kImp":"주간 보고가 벌커 용선·배선 의사결정에 활용된다.","eImp":"The weekly report informs bulker chartering and deployment.","url":"https://www.balticexchange.com/en/data-services/WeeklyRoundup/dry/news/2026/bulk-report-week-8.html"}]},{"code":"GEO","type":"news","kTitle":"Section 16. Chokepoints (Geopolitics)","eTitle":"Section 16. Chokepoints (Geopolitics)","items":[{"code":"GEO","title":"호르무즈 이후, 글로벌 길목 리스크 재편","src":"ION Analytics","date":"2026-06","kSum":"호르무즈 사태 이후 글로벌 공급망 리스크가 다른 길목으로 재편되고 있다는 분석이 나왔다. 말라카·바브엘만데브 등 대체 길목 의존도가 부각된다.","eSum":"Analysis finds global supply-chain risk redistributing to other chokepoints after Hormuz, raising the profile of alternatives like Malacca and Bab-el-Mandeb.","kImp":"단일 길목 의존이 공급망 취약성을 노출한다.","eImp":"Single-chokepoint reliance exposes supply-chain fragility.","url":"https://ionanalytics.com/insights/blackpeak/after-hormuz-the-global-chokepoints-redefining-global-supply-chain-risk/"},{"code":"GEO","title":"홍해·호르무즈 동시 봉쇄…'이중 길목' 위기","src":"Simple Forwarding","date":"2026-06","kSum":"현대사 처음으로 중동 양대 해상회랑인 홍해와 호르무즈가 동시에 봉쇄되며 '이중 길목' 위기가 현실화됐다. 우회 비용·기간이 급증했다.","eSum":"For the first time in modern history, both Mideast corridors — the Red Sea and Hormuz — are simultaneously blocked, realising a 'double chokepoint' crisis with surging detour cost and time.","kImp":"동시 봉쇄가 아시아-유럽·중동 항로를 구조적으로 압박한다.","eImp":"Simultaneous closures structurally pressure Asia–Europe/Mideast lanes.","url":"https://simpleforwarding.com/the-double-chokepoint-navigating-the-simultaneous-blockade-of-the-red-sea-and-the-strait-of-hormuz/"},{"code":"GEO","title":"희망봉 우회, 3,500~4,000해리·10~14일 추가","src":"Carra Globe","date":"2026-06","kSum":"희망봉 우회는 아시아-유럽·아시아-중동 항로에 약 3,500~4,000해리, 10~14일을 추가한다. 가용 선복 수요 급증으로 운임이 크게 올랐다.","eSum":"The Cape of Good Hope detour adds ~3,500–4,000 nm and 10–14 days on Asia–Europe/Asia–Mideast lanes, with surging capacity demand lifting rates sharply.","kImp":"장거리 우회가 선복 흡수·연료비 증가를 동반한다.","eImp":"Long detours absorb capacity and raise fuel costs.","url":"https://carraglobe.com/strait-of-hormuz-closure-2026/"},{"code":"GEO","title":"UN, 호르무즈 위기가 드러낸 해운 취약성 경고","src":"UN News","date":"2026-06","kSum":"UN은 호르무즈 위기가 글로벌 해운의 취약성을 드러냈다며 길목 분쟁이 무역·에너지 안보에 미치는 파급을 경고했다.","eSum":"The UN warned the Hormuz crisis exposed global shipping vulnerabilities, flagging how chokepoint conflict ripples through trade and energy security.","kImp":"국제기구 경고가 길목 리스크 대응 공조를 촉구한다.","eImp":"International warnings spur coordinated chokepoint-risk responses.","url":"https://news.un.org/en/story/2026/04/1167383"},{"code":"GEO","title":"파나마 운하, CK허치슨 항만계약 위헌 판결 여진","src":"Breaking Defense","date":"2026-06","kSum":"파나마 대법원이 CK허치슨의 운하 인근 항만 운영계약을 위헌으로 판결한 여진이 이어진다. 지정학·환경 압력이 운하 운영 불확실성을 키운다.","eSum":"Fallout continues from Panama's Supreme Court ruling that CK Hutchison's canal-area port contract was unconstitutional, as geopolitical and environmental pressures raise operating uncertainty.","kImp":"운하 거버넌스 변수가 대체 길목 리스크를 가중한다.","eImp":"Canal-governance risk compounds alternative-chokepoint exposure.","url":"https://breakingdefense.com/2026/04/hormuz-disruption-will-change-trade-and-defense-at-other-chokepoints/"},{"code":"GEO","title":"채텀하우스, \"호르무즈보다 위험한 길목\" 분석","src":"Chatham House","date":"2026-06","kSum":"채텀하우스는 호르무즈보다 더 위험할 수 있는 해상 길목들을 분석하며 말라카·수에즈·파나마의 구조적 취약성을 짚었다.","eSum":"Chatham House analysed maritime chokepoints that could be worse than Hormuz, highlighting structural vulnerabilities at Malacca, Suez and Panama.","kImp":"다중 길목 취약성 점검이 항로 리스크 분산을 돕는다.","eImp":"Mapping multi-chokepoint vulnerability aids route-risk diversification.","url":"https://www.chathamhouse.org/publications/the-world-today/2026-06/maritime-chokepoints-could-be-worse-hormuz"},{"code":"GEO","title":"수에즈 운하 교통, 홍해 우회로 정상比 부진 지속","src":"Logfret","date":"2026-06","kSum":"수에즈 운하 교통이 홍해 우회 지속으로 2026년에도 정상 대비 부진하다. 통항 정상화 시점이 불투명하다.","eSum":"Suez Canal traffic remains subdued versus normal into 2026 as Red Sea rerouting persists, with normalisation timing unclear.","kImp":"운하 부진이 운하청 수입·물류 시간에 부담을 준다.","eImp":"Subdued canal traffic strains revenue and logistics timing.","url":"https://logfret.com/logfret-insights/suez-canal-traffic-remains-subdued-as-red-sea-rerouting-persists-into-2026/"},{"code":"GEO","title":"홍해 재개가 공급망에 줄 영향 분석","src":"Zencargo","date":"2026-06","kSum":"홍해·수에즈 재개가 공급망에 미칠 영향을 분석한 자료가 나왔다. 재개 시 아시아-유럽 항로 운송시간이 10~15일 단축될 수 있다.","eSum":"Analysis assessed how a Red Sea/Suez reopening would affect supply chains, noting it could cut Asia–Europe transit by 10–15 days.","kImp":"재개 시나리오가 재고·계약 전략 재설정을 요구한다.","eImp":"Reopening scenarios call for resetting inventory and contracts.","url":"https://www.zencargo.com/resources/red-sea-reopening-2026/"},{"code":"GEO","title":"2026 수에즈·홍해 항로 리스크·운영 영향","src":"SeaRates","date":"2026-06","kSum":"2026년 수에즈·홍해 항로의 리스크와 운영 영향을 정리한 분석이 공개됐다. 항로·기항·보험 측면의 실무 고려사항을 제시했다.","eSum":"An analysis outlined 2026 Suez/Red Sea route risks and operational impacts, covering routing, port-call and insurance considerations.","kImp":"항로 리스크 점검이 운항 계획의 회복탄력성을 높인다.","eImp":"Route-risk review improves voyage-planning resilience.","url":"https://www.searates.com/blog/post/suez-canal-and-red-sea-shipping-in-2026-risks-routes-and-operational-impact"}]},{"code":"TW","type":"news","kTitle":"Section 17. TradeWinds — Ship Management","eTitle":"Section 17. TradeWinds — Ship Management","items":[{"code":"TW","title":"BSM, 세계 첫 암모니아 벙커링선 기술관리 수주","src":"Bernhard Schulte","date":"2026-06","kSum":"6월 이토추가 세계 최초 암모니아 벙커링선 건조 계약을 체결했고, 베른하르트 슐테(BSM)가 기술관리를 맡는다. 2027년 인도 예정이다.","eSum":"In June ITOCHU contracted the world's first ammonia bunkering vessel, with Bernhard Schulte Shipmanagement providing technical management; delivery is due 2027.","kImp":"신연료 인프라선 관리 수주가 선박관리사 역량을 입증한다.","eImp":"Managing a novel-fuel infrastructure ship showcases manager capability.","url":"https://www.bs-shipmanagement.com/"},{"code":"TW","title":"BSM, 첫 메탄올 이중연료 벌커 '브레이브 파이어니어' 인수","src":"TradeWinds","date":"2026-06","kSum":"BSM이 1월 15일 첫 메탄올 이중연료 벌커 '브레이브 파이어니어(M.V. Brave Pioneer)'를 인수했다. 대체연료 선대 관리 역량을 확장한다.","eSum":"BSM took delivery of its first methanol dual-fuel bulker, M.V. Brave Pioneer, on 15 January, expanding its alt-fuel fleet management capability.","kImp":"이중연료선 관리 경험이 선대 탈탄소 수요에 대응한다.","eImp":"Dual-fuel management experience meets fleet decarbonisation demand.","url":"https://www.tradewindsnews.com/tag/bernhard_schulte_shipmanagement"},{"code":"TW","title":"앵글로-이스턴, 이중연료 50척 이상·신조 87척 관리","src":"Anglo-Eastern","date":"2026-06","kSum":"앵글로-이스턴이 다양한 연료의 이중연료선 50척 이상을 관리하며 신조·프로젝트 87척을 진행한다. 풍력보조 아프라막스 '브랜즈해치'도 포함된다.","eSum":"Anglo-Eastern manages 50+ dual-fuel vessels and 87 under newbuilding/project management, including the first wind-assisted aframax Brands Hatch.","kImp":"신조·신연료 포트폴리오 확대가 관리사 경쟁력을 강화한다.","eImp":"A growing newbuild and novel-fuel portfolio strengthens manager competitiveness.","url":"https://www.tradewindsnews.com/tag/anglo-eastern_ship_management"},{"code":"TW","title":"선박관리사, 진화하는 역할…기술·디지털·복지 통합","src":"Maritime Executive","date":"2026-06","kSum":"선박관리사의 역할이 기술관리를 넘어 디지털·연료전환·선원복지를 아우르는 통합 서비스로 진화하고 있다.","eSum":"The ship manager's role is evolving beyond technical management into integrated services spanning digital, fuel transition and crew welfare.","kImp":"통합 서비스 역량이 화주·선주 선택의 기준이 된다.","eImp":"Integrated-service capability becomes a key selection criterion.","url":"https://maritime-executive.com/magazine/evolving-role-for-ship-managers"},{"code":"TW","title":"앵글로-이스턴, 차세대 풍력보조 아프라막스 관리","src":"Anglo-Eastern","date":"2026-06","kSum":"앵글로-이스턴이 첫 풍력보조 아프라막스 '브랜즈해치(Brands Hatch)'와 차세대 해상지원선 '윈드캣 로테르담'의 신조·관리를 맡는다.","eSum":"Anglo-Eastern manages the first wind-assisted aframax Brands Hatch and the next-gen offshore support vessel Windcat Rotterdam under newbuilding/project management.","kImp":"풍력보조선 관리 경험이 효율·배출 규제 대응을 강화한다.","eImp":"Wind-assist management experience strengthens efficiency and emissions compliance.","url":"https://www.marinelink.com/news/maritime/ship-management"},{"code":"TW","title":"선박관리, 미래 선원 공급원 확보가 과제","src":"Splash247","date":"2026-06","kSum":"\"내일의 선원은 어디서 올 것인가\"라는 화두 속에 선박관리사들이 교육·훈련 투자와 신규 인력풀 개척에 나서고 있다.","eSum":"Amid the question of where tomorrow's seafarers will come from, ship managers are investing in training and opening new talent pools.","kImp":"인력 파이프라인 확보가 관리 품질·연속성을 좌우한다.","eImp":"Securing the talent pipeline determines management quality and continuity.","url":"https://splash247.com/where-will-tomorrows-seafarers-come-from/"}]},{"code":"HOT","type":"news","kTitle":"Section 18. Lloyd’s List Hot Topic — Strait of Hormuz Crisis","eTitle":"Section 18. Lloyd’s List Hot Topic — Strait of Hormuz Crisis","items":[{"code":"HOT","title":"이란 '폐쇄' 선언에도 주말 내내 호르무즈 통항 지속","src":"Lloyd's List","date":"2026-06","kSum":"이란이 6월 21일자로 호르무즈 해협 폐쇄와 미준수 선박에 대한 조치를 거듭 주장했음에도, 선박들은 주말 내내 통항을 지속했다.","eSum":"Ships kept transiting the Strait of Hormuz over the weekend despite Iran's renewed claims it had closed the waterway and would act against non-compliant vessels as of 21 June.","kImp":"선언과 실제 통항의 괴리가 시장 불확실성을 키운다.","eImp":"The gap between declaration and actual transit fuels market uncertainty.","url":"https://www.lloydslist.com/hot-topics/strait-of-hormuz-crisis"},{"code":"HOT","title":"북측 회랑 통항요건 강화…48시간 전 사전요청","src":"Hormuz Strait Monitor","date":"2026-06","kSum":"라라크섬 인근 북측 항로는 48시간 전 선박정보 사전요청, 최대 5일 유효 일회용 허가, VHF 호출 대비를 요구한다. 오만 수역 남측 항로가 선호된다.","eSum":"The northern route near Larak Island requires transit requests 48 hours ahead, a single-use permit valid up to five days and VHF-hailing readiness; the southern Omani lane is preferred.","kImp":"통항요건 이해가 지연·나포 리스크를 줄인다.","eImp":"Knowing transit requirements reduces delay and seizure risk.","url":"https://hormuzstraitmonitor.com/"},{"code":"HOT","title":"로이즈리스트 \"600척 이상 중동만에 발 묶여\"","src":"Lloyd's List","date":"2026-06","kSum":"로이즈리스트는 600척 이상이 여전히 중동만에 발이 묶여 있으며, 일부 다크선박이 주류 무역으로 복귀하고 있다고 분석했다.","eSum":"Lloyd's List reports more than 600 vessels still stuck in the Middle East Gulf, with some shadow-fleet ships slipping back into mainstream trades.","kImp":"체선 누적이 통항 재개 후 운임 변동성을 키운다.","eImp":"Accumulated congestion amplifies post-reopening rate volatility.","url":"https://www.lloydslist.com/LL1156883/The-Week-in-Charts-Shadow-fleet-ships-slip-back-to-mainstream-trades--More-than-600-vessels-still-stuck-in-Middle-East-Gulf"},{"code":"HOT","title":"CNBC \"재개돼도 적체 해소에 수주 소요\"","src":"CNBC","date":"2026-06-18","kSum":"CNBC는 미·이란 종전 합의 보도에 유가가 80달러 아래로 내렸으나, 호르무즈 선박 적체 해소에 수 주가 걸릴 것이라고 전했다. 유조선·LNG선이 우선 통항한다.","eSum":"CNBC reported oil dipped below $80 on US–Iran deal news, but clearing the Hormuz backlog will take weeks, with tankers and LNG carriers getting priority.","kImp":"적체 해소 지연이 에너지 수송 정상화를 늦춘다.","eImp":"A slow backlog clearance delays normalisation of energy shipping.","url":"https://www.cnbc.com/amp/2026/06/18/strait-hormuz-reopening-shipping-oil.html"},{"code":"HOT","title":"호르무즈, 세계 해상 원유·LNG 20% 통과 길목","src":"CSIS","date":"2026-06","kSum":"호르무즈는 세계 일일 원유의 약 20%와 LNG의 약 20%가 통과하는 최대 에너지 길목이다. 봉쇄 장기화가 에너지 가격·물류에 직접 충격을 준다.","eSum":"Hormuz carries ~20% of the world's daily oil and ~20% of LNG; a prolonged closure directly shocks energy prices and logistics.","kImp":"길목 의존도가 에너지 안보 취약성을 드러낸다.","eImp":"Chokepoint dependence exposes energy-security fragility.","url":"https://www.csis.org/analysis/strait-hormuz-8-charts"},{"code":"HOT","title":"윈드워드, 호르무즈 통항 실시간 인텔리전스 제공","src":"Windward","date":"2026-06","kSum":"윈드워드(Windward)는 호르무즈 통항 상황에 대한 일일 인텔리전스를 제공하며, 다크선박 활동과 통항 패턴 변화를 추적한다.","eSum":"Windward provides daily intelligence on Hormuz transit, tracking shadow-fleet activity and shifting transit patterns.","kImp":"실시간 인텔리전스가 통항 의사결정의 근거가 된다.","eImp":"Real-time intelligence underpins transit decision-making.","url":"https://insights.windward.ai/"},{"code":"HOT","title":"로이즈리스트, 호르무즈 공격 지도·목록 운영","src":"Lloyd's List","date":"2026-06","kSum":"로이즈리스트가 호르무즈 위기 관련 공격 지도와 목록을 운영하며 선박 피격·나포 사건을 추적·집계한다.","eSum":"Lloyd's List maintains a map and list of attacks for the Hormuz crisis, tracking and tallying vessel strikes and seizures.","kImp":"사건 데이터베이스가 통항 위험도 평가에 활용된다.","eImp":"The incident database supports transit-risk assessment.","url":"https://www.lloydslist.com/hot-topics/strait-of-hormuz-crisis/map-and-list-of-attacks"},{"code":"HOT","title":"로이즈리스트, 호르무즈 핫토픽 상시 추적","src":"Lloyd's List","date":"2026-06","kSum":"로이즈리스트가 호르무즈 핫토픽 페이지에서 통항·공격·정책 변화를 상시 추적·집계한다. 분쟁 추이의 핵심 레퍼런스로 활용된다.","eSum":"Lloyd's List continuously tracks transit, attacks and policy shifts on its Hormuz hot-topic page, a key reference for the crisis.","kImp":"집계 데이터가 통항 리스크 판단의 근거가 된다.","eImp":"Aggregated data underpins transit-risk judgement.","url":"https://www.lloydslist.com/hot-topics/strait-of-hormuz"},{"code":"HOT","title":"알자지라 \"휴전에도 호르무즈 통항은 소강\"","src":"Al Jazeera","date":"2026-06","kSum":"알자지라는 미·이란 휴전 보도에도 호르무즈 통항이 소강 상태에 머물렀다고 전했다. 선사들의 관망세가 이어졌다.","eSum":"Al Jazeera reported Hormuz transit remained at a trickle despite US–Iran ceasefire news, as carriers stayed in watchful waiting.","kImp":"휴전 신호와 실제 통항의 시차가 시장 불확실성을 키운다.","eImp":"The lag between ceasefire signals and actual transit fuels uncertainty.","url":"https://www.aljazeera.com/economy/2026/4/10/shipping-in-strait-of-hormuz-at-a-trickle-despite-us-iran-ceasefire"}]}]};
